const std = @import("std");
const mem = std.mem;
const math = std.math;
const vector = std.meta.Vector;

const Tensor = struct {
    allocator: mem.Allocator,
    data: []f32,
    shape: []usize,
    strides: []usize,

    pub fn init(allocator: mem.Allocator, shape: []const usize) !Tensor {
        var self: Tensor = .{ .allocator = allocator, .shape = try allocator.dupe(usize, shape), .strides = try allocator.alloc(usize, shape.len), .data = undefined };
        var size: usize = 1;
        var i = shape.len;
        while (i > 0) {
            i -= 1;
            self.strides[i] = size;
            size *= shape[i];
        }
        self.data = try allocator.alloc(f32, size);
        return self;
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    pub fn copy(self: *const Tensor, allocator: mem.Allocator) !Tensor {
        var new = try init(allocator, self.shape);
        @memcpy(new.data, self.data);
        return new;
    }

    pub fn fill(self: *Tensor, value: f32) void {
        @memset(self.data, value);
    }

    pub fn getIndex(self: *const Tensor, indices: []const usize) usize {
        var idx: usize = 0;
        for (indices, self.strides) |i, s| idx += i * s;
        return idx;
    }

    pub fn get(self: *const Tensor, indices: []const usize) f32 {
        return self.data[self.getIndex(indices)];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f32) void {
        self.data[self.getIndex(indices)] = value;
    }

    pub fn add(self: *Tensor, other: *const Tensor) !void {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            const b = @as(vector(8, f32), other.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a + b);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] += other.data[j];
        }
    }

    pub fn sub(self: *Tensor, other: *const Tensor) !void {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            const b = @as(vector(8, f32), other.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a - b);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] -= other.data[j];
        }
    }

    pub fn mul(self: *Tensor, other: *const Tensor) !void {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            const b = @as(vector(8, f32), other.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a * b);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] *= other.data[j];
        }
    }

    pub fn div(self: *Tensor, other: *const Tensor) !void {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            const b = @as(vector(8, f32), other.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a / b);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] /= other.data[j];
        }
    }

    pub fn addScalar(self: *Tensor, scalar: f32) void {
        const s_vec = @splat(8, scalar);
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a + s_vec);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] += scalar;
        }
    }

    pub fn subScalar(self: *Tensor, scalar: f32) void {
        const s_vec = @splat(8, scalar);
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a - s_vec);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] -= scalar;
        }
    }

    pub fn mulScalar(self: *Tensor, scalar: f32) void {
        const s_vec = @splat(8, scalar);
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a * s_vec);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] *= scalar;
        }
    }

    pub fn divScalar(self: *Tensor, scalar: f32) void {
        const s_vec = @splat(8, scalar);
        const len = self.data.len / 8;
        var i: usize = 0;
        while (i < len) : (i += 1) {
            const a = @as(vector(8, f32), self.data[i*8..i*8+8].*);
            self.data[i*8..i*8+8].* = @as([8]f32, a / s_vec);
        }
        for (i * 8..self.data.len) |j| {
            self.data[j] /= scalar;
        }
    }

    pub fn exp(self: *Tensor) void {
        for (self.data) |*val| val.* = math.exp(val.*);
    }

    pub fn log(self: *Tensor) void {
        for (self.data) |*val| val.* = math.log(val.*);
    }

    pub fn sin(self: *Tensor) void {
        for (self.data) |*val| val.* = math.sin(val.*);
    }

    pub fn cos(self: *Tensor) void {
        for (self.data) |*val| val.* = math.cos(val.*);
    }

    pub fn tan(self: *Tensor) void {
        for (self.data) |*val| val.* = math.tan(val.*);
    }

    pub fn sqrt(self: *Tensor) void {
        for (self.data) |*val| val.* = math.sqrt(val.*);
    }

    pub fn pow(self: *Tensor, exp: f32) void {
        for (self.data) |*val| val.* = math.pow(f32, val.*, exp);
    }

    pub fn abs(self: *Tensor) void {
        for (self.data) |*val| val.* = math.fabs(val.*);
    }

    pub fn max(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var new_shape = try allocator.dupe(usize, self.shape);
        new_shape[axis] = 1;
        var result = try init(allocator, new_shape);
        allocator.free(new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var max_val = -math.inf(f32);
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                indices[axis] = j;
                max_val = math.max(max_val, self.get(indices));
            }
            indices[axis] = 0;
            result.set(indices, max_val);
            var carry = true;
            var k = self.shape.len;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    indices[k] += 1;
                    if (indices[k] < self.shape[k]) carry = false else indices[k] = 0;
                }
            }
            if (carry) break;
        }
        return result;
    }

    pub fn min(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var new_shape = try allocator.dupe(usize, self.shape);
        new_shape[axis] = 1;
        var result = try init(allocator, new_shape);
        allocator.free(new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var min_val = math.inf(f32);
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                indices[axis] = j;
                min_val = math.min(min_val, self.get(indices));
            }
            indices[axis] = 0;
            result.set(indices, min_val);
            var carry = true;
            var k = self.shape.len;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    indices[k] += 1;
                    if (indices[k] < self.shape[k]) carry = false else indices[k] = 0;
                }
            }
            if (carry) break;
        }
        return result;
    }

    pub fn sum(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var new_shape = try allocator.dupe(usize, self.shape);
        new_shape[axis] = 1;
        var result = try init(allocator, new_shape);
        allocator.free(new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var sum_val: f32 = 0.0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                indices[axis] = j;
                sum_val += self.get(indices);
            }
            indices[axis] = 0;
            result.set(indices, sum_val);
            var carry = true;
            var k = self.shape.len;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    indices[k] += 1;
                    if (indices[k] < self.shape[k]) carry = false else indices[k] = 0;
                }
            }
            if (carry) break;
        }
        return result;
    }

    pub fn mean(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var s = try self.sum(allocator, axis);
        defer s.deinit();
        s.divScalar(@floatFromInt(self.shape[axis]));
        return s;
    }

    pub fn variance(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var m = try self.mean(allocator, axis);
        defer m.deinit();
        var diff = try self.copy(allocator);
        defer diff.deinit();
        var b_shape = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(b_shape);
        @memcpy(b_shape, self.shape);
        b_shape[axis] = 1;
        var b_mean = try m.broadcast(allocator, b_shape);
        defer b_mean.deinit();
        try diff.sub(b_mean);
        try diff.mul(diff);
        var v = try diff.sum(allocator, axis);
        v.divScalar(@floatFromInt(self.shape[axis] - 1));
        return v;
    }

    pub fn stddev(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var v = try self.variance(allocator, axis);
        defer v.deinit();
        v.sqrt();
        return try v.copy(allocator);
    }

    pub fn argmax(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var new_shape = try allocator.dupe(usize, self.shape);
        new_shape[axis] = 1;
        var result = try init(allocator, new_shape);
        allocator.free(new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var max_val = -math.inf(f32);
            var max_idx: usize = 0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                indices[axis] = j;
                const val = self.get(indices);
                if (val > max_val) {
                    max_val = val;
                    max_idx = j;
                }
            }
            indices[axis] = 0;
            result.set(indices, @floatFromInt(max_idx));
            var carry = true;
            var k = self.shape.len;
            while (carry and k > 0) {
                k -= 1;
                if (k != axis) {
                    indices[k] += 1;
                    if (indices[k] < self.shape[k]) carry = false else indices[k] = 0;
                }
            }
            if (carry) break;
        }
        return result;
    }

