            var min_val = math.inf(f32);
            var min_idx: usize = 0;
            var j: usize = 0;
            while (j < self.shape[axis]) : (j += 1) {
                indices[axis] = j;
                const val = self.get(indices);
                if (val < min_val) {
                    min_val = val;
                    min_idx = j;
                }
            }
            indices[axis] = 0;
            result.set(indices, @floatFromInt(min_idx));
            var carry = true;
