    pub fn broadcast(self: *const Tensor, allocator: mem.Allocator, target_shape: []const usize) !Tensor {
        if (self.shape.len != target_shape.len) return error.ShapeMismatch;
        var new_tensor = try init(allocator, target_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.shape.len);
            defer allocator.free(src_indices);
            for (0..self.shape.len) |i| {
                src_indices[i] = if (self.shape[i] == 1) 0 else indices[i];
            }
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < target_shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn reshape(self: *Tensor, new_shape: []const usize) !void {
        var new_size: usize = 1;
        for (new_shape) |s| new_size *= s;
        if (new_size != self.data.len) return error.InvalidReshape;
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
        var stride: usize = 1;
        var i = new_shape.len;
        while (i > 0) {
            i -= 1;
            self.strides[i] = stride;
            stride *= new_shape[i];
        }
    }

    pub fn transpose(self: *const Tensor, allocator: mem.Allocator, axes: []const usize) !Tensor {
        if (axes.len != self.shape.len) return error.InvalidAxes;
        var new_shape = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(new_shape);
        for (axes, 0..) |ax, i| new_shape[i] = self.shape[ax];
        var new_tensor = try init(allocator, new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.shape.len);
            defer allocator.free(src_indices);
            for (axes, 0..) |ax, i| src_indices[ax] = indices[i];
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_tensor.shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn slice(self: *const Tensor, allocator: mem.Allocator, ranges: []const [2]usize) !Tensor {
        if (ranges.len != self.shape.len) return error.InvalidRanges;
        var new_shape = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(new_shape);
        for (ranges, 0..) |r, i| new_shape[i] = r[1] - r[0];
        var new_tensor = try init(allocator, new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.shape.len);
            defer allocator.free(src_indices);
            for (ranges, 0..) |r, i| src_indices[i] = indices[i] + r[0];
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn concatenate(allocator: mem.Allocator, tensors: []const Tensor, axis: usize) !Tensor {
        if (tensors.len == 0) return error.EmptyConcat;
        const ndim = tensors[0].shape.len;
        if (axis >= ndim) return error.InvalidAxis;
        for (tensors) |ten| {
            if (ten.shape.len != ndim) return error.ShapeMismatch;
            for (0..ndim) |i| {
                if (i != axis and ten.shape[i] != tensors[0].shape[i]) return error.ShapeMismatch;
            }
        }
        var new_shape = try allocator.dupe(usize, tensors[0].shape);
        for (tensors[1..]) |ten| new_shape[axis] += ten.shape[axis];
        var new_tensor = try init(allocator, new_shape);
        allocator.free(new_shape);
        var offset: usize = 0;
        for (tensors) |ten| {
            @memcpy(new_tensor.data[offset..offset + ten.data.len], ten.data);
            offset += ten.data.len;
        }
        return new_tensor;
    }

    pub fn stack(allocator: mem.Allocator, tensors: []const Tensor, axis: usize) !Tensor {
        if (tensors.len == 0) return error.EmptyStack;
        const ndim = tensors[0].shape.len;
        if (axis > ndim) return error.InvalidAxis;
        for (tensors) |ten| {
            if (ten.shape.len != ndim or !mem.eql(usize, ten.shape, tensors[0].shape)) return error.ShapeMismatch;
        }
        var new_shape = try allocator.alloc(usize, ndim + 1);
        defer allocator.free(new_shape);
        var k: usize = 0;
        for (0..ndim + 1) |i| {
            if (i == axis) new_shape[i] = tensors.len else {
                new_shape[i] = tensors[0].shape[k];
                k += 1;
            }
        }
        var new_tensor = try init(allocator, new_shape);
        const slice_size = tensors[0].data.len;
        for (0..tensors.len) |i| {
            @memcpy(new_tensor.data[i * slice_size .. i * slice_size + slice_size], tensors[i].data);
        }
        return new_tensor;
    }

    pub fn tile(self: *const Tensor, allocator: mem.Allocator, reps: []const usize) !Tensor {
        if (reps.len != self.shape.len) return error.InvalidReps;
        var new_shape = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(new_shape);
        for (0..self.shape.len) |i| new_shape[i] = self.shape[i] * reps[i];
        var new_tensor = try init(allocator, new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var src_indices = try allocator.alloc(usize, self.shape.len);
            defer allocator.free(src_indices);
            for (0..self.shape.len) |i| src_indices[i] = indices[i] % self.shape[i];
            const val = self.get(src_indices);
            new_tensor.set(indices, val);
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn pad(self: *const Tensor, allocator: mem.Allocator, pads: []const [2]usize) !Tensor {
        if (pads.len != self.shape.len) return error.InvalidPads;
        var new_shape = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(new_shape);
        for (0..self.shape.len) |i| new_shape[i] = self.shape[i] + pads[i][0] + pads[i][1];
        var new_tensor = try init(allocator, new_shape);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            var is_padding = false;
            var src_indices = try allocator.alloc(usize, self.shape.len);
            defer allocator.free(src_indices);
            for (0..self.shape.len) |i| {
                if (indices[i] < pads[i][0] or indices[i] >= pads[i][0] + self.shape[i]) is_padding = true else src_indices[i] = indices[i] - pads[i][0];
            }
            if (!is_padding) {
                const val = self.get(src_indices);
                new_tensor.set(indices, val);
            }
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                indices[j] += 1;
                if (indices[j] < new_shape[j]) {
                    carry = false;
                } else {
                    indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn clip(self: *Tensor, min_val: f32, max_val: f32) void {
        for (self.data) |*val| val.* = math.clamp(val.*, min_val, max_val);
    }

    pub fn normalize(self: *Tensor, allocator: mem.Allocator, axis: usize, epsilon: f32) !void {
        var mean_t = try self.mean(allocator, axis);
        defer mean_t.deinit();
        var var_t = try self.variance(allocator, axis);
        defer var_t.deinit();
        var_t.addScalar(epsilon);
        var_t.sqrt();
        var b_shape = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(b_shape);
        @memcpy(b_shape, self.shape);
        b_shape[axis] = 1;
        var b_mean = try mean_t.broadcast(allocator, b_shape);
        defer b_mean.deinit();
        try self.sub(&b_mean);
        var b_std = try var_t.broadcast(allocator, b_shape);
        defer b_std.deinit();
        try self.div(&b_std);
    }

    pub fn oneHot(self: *const Tensor, allocator: mem.Allocator, num_classes: usize) !Tensor {
        if (self.shape.len != 1) return error.InvalidForOneHot;
        var new_shape = [_]usize{ self.shape[0], num_classes };
        var new_tensor = try init(allocator, &new_shape);
        for (0..self.shape[0]) |i| {
            const class_idx = @intFromFloat(self.get(&.{i}));
            if (class_idx < num_classes) new_tensor.set(&.{ i, class_idx }, 1.0);
        }
        return new_tensor;
    }

    pub fn cumsum(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var new_tensor = try self.copy(allocator);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            if (indices[axis] > 0) {
                indices[axis] -= 1;
                const prev = new_tensor.get(indices);
                indices[axis] += 1;
                const curr = new_tensor.get(indices);
                new_tensor.set(indices, prev + curr);
            }
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                if (j != axis) {
                    indices[j] += 1;
                    if (indices[j] < self.shape[j]) carry = false else indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn cumprod(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        var new_tensor = try self.copy(allocator);
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        while (true) {
            if (indices[axis] > 0) {
                indices[axis] -= 1;
                const prev = new_tensor.get(indices);
                indices[axis] += 1;
                const curr = new_tensor.get(indices);
                new_tensor.set(indices, prev * curr);
            }
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                if (j != axis) {
                    indices[j] += 1;
                    if (indices[j] < self.shape[j]) carry = false else indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn sort(self: *const Tensor, allocator: mem.Allocator, axis: usize, descending: bool) !Tensor {
        var new_tensor = try self.copy(allocator);
        const dim = self.shape[axis];
        var indices = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var temp = try allocator.alloc(f32, dim);
        defer allocator.free(temp);
        while (true) {
            for (0..dim) |i| {
                indices[axis] = i;
                temp[i] = new_tensor.get(indices);
            }
            std.sort.pdq(f32, temp, {}, if (descending) std.sort.desc(f32) else std.sort.asc(f32));
            for (0..dim) |i| {
                indices[axis] = i;
                new_tensor.set(indices, temp[i]);
            }
            var carry = true;
            var j = self.shape.len;
            while (carry and j > 0) {
                j -= 1;
                if (j != axis) {
                    indices[j] += 1;
                    if (indices[j] < self.shape[j]) carry = false else indices[j] = 0;
                }
            }
            if (carry) break;
        }
        return new_tensor;
    }

    pub fn unique(self: *const Tensor, allocator: mem.Allocator) !Tensor {
        var set = std.AutoHashMap(f32, void).init(allocator);
        defer set.deinit();
        for (self.data) |val| try set.put(val, {});
        var unique_vals = try allocator.alloc(f32, set.count());
        defer allocator.free(unique_vals);
        var iter = set.keyIterator();
        var i: usize = 0;
        while (iter.next()) |key| {
            unique_vals[i] = key.*;
            i += 1;
        }
        var result = try init(allocator, &.{set.count()});
        @memcpy(result.data, unique_vals);
        return result;
    }

    pub fn isClose(self: *const Tensor, other: *const Tensor, rtol: f32, atol: f32) bool {
        if (!mem.eql(usize, self.shape, other.shape)) return false;
        for (self.data, other.data) |a, b| {
            if (math.fabs(a - b) > atol + rtol * math.fabs(b)) return false;
        }
        return true;
    }

    pub fn randomUniform(self: *Tensor, min: f32, max: f32, seed: u64) void {
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        for (self.data) |*val| val.* = rand.float(f32) * (max - min) + min;
    }

    pub fn randomNormal(self: *Tensor, mean: f32, stddev: f32, seed: u64) void {
        var prng = std.rand.DefaultPrng.init(seed);
        const rand = prng.random();
        var i: usize = 0;
        while (i < self.data.len) : (i += 2) {
            const u1 = rand.float(f32);
            const u2 = rand.float(f32);
            const z0 = math.sqrt(-2.0 * math.log(u1)) * math.cos(2.0 * math.pi * u2);
            self.data[i] = mean + stddev * z0;
            if (i + 1 < self.data.len) {
                const z1 = math.sqrt(-2.0 * math.log(u1)) * math.sin(2.0 * math.pi * u2);
                self.data[i + 1] = mean + stddev * z1;
            }
        }
    }

    pub fn arange(allocator: mem.Allocator, start: f32, end: f32, step: f32) !Tensor {
        const num = @intFromFloat(math.ceil((end - start) / step));
        var t = try init(allocator, &.{@intCast(num)});
        var val = start;
        for (t.data) |*d| {
            d.* = val;
            val += step;
        }
        return t;
    }

    pub fn linspace(allocator: mem.Allocator, start: f32, end: f32, num: usize) !Tensor {
        var t = try init(allocator, &.{num});
        if (num == 1) {
            t.data[0] = start;
            return t;
        }
        const step = (end - start) / @floatFromInt(num - 1);
        var val = start;
        for (0..num - 1) |i| {
            t.data[i] = val;
            val += step;
        }
        t.data[num - 1] = end;
        return t;
    }

    pub fn eye(allocator: mem.Allocator, n: usize) !Tensor {
        var t = try init(allocator, &.{n, n});
        for (0..n) |i| t.set(&.{i, i}, 1.0);
        return t;
    }

    pub fn zeros(allocator: mem.Allocator, shape: []const usize) !Tensor {
        var t = try init(allocator, shape);
        t.fill(0.0);
        return t;
    }

    pub fn ones(allocator: mem.Allocator, shape: []const usize) !Tensor {
        var t = try init(allocator, shape);
        t.fill(1.0);
        return t;
    }

    pub fn full(allocator: mem.Allocator, shape: []const usize, value: f32) !Tensor {
        var t = try init(allocator, shape);
        t.fill(value);
        return t;
    }

    pub fn matmul(a: *const Tensor, b: *const Tensor, allocator: mem.Allocator) !Tensor {
        if (a.shape.len != 2 or b.shape.len != 2 or a.shape[1] != b.shape[0]) return error.InvalidMatmul;
        const m = a.shape[0];
        const k = a.shape[1];
        const n = b.shape[1];
        var c = try init(allocator, &.{m, n});
        for (0..m) |i| {
            for (0..n) |j| {
                var sum: f32 = 0.0;
                var p: usize = 0;
                while (p < k / 8 * 8) : (p += 8) {
                    const av = @as(vector(8, f32), a.data[i * k + p .. i * k + p + 8].*);
                    const bv = @as(vector(8, f32), b.data[p * n + j .. (p + 8) * n + j : n].*);
                    sum += @reduce(.Add, av * bv);
                }
                for (p..k) |q| sum += a.data[i * k + q] * b.data[q * n + j];
                c.set(&.{i, j}, sum);
            }
        }
        return c;
    }

    pub fn conv2d(input: *const Tensor, kernel: *const Tensor, allocator: mem.Allocator, stride: [2]usize, padding: [2]usize) !Tensor {
        if (input.shape.len != 4 or kernel.shape.len != 4 or input.shape[3] != kernel.shape[2]) return error.InvalidConv2d;
        const batch = input.shape[0];
        const ih = input.shape[1];
        const iw = input.shape[2];
        const ic = input.shape[3];
        const kh = kernel.shape[0];
        const kw = kernel.shape[1];
        const oc = kernel.shape[3];
        const oh = (ih + 2 * padding[0] - kh) / stride[0] + 1;
        const ow = (iw + 2 * padding[1] - kw) / stride[1] + 1;
        var output = try init(allocator, &.{batch, oh, ow, oc});
        var padded = if (padding[0] > 0 or padding[1] > 0) try input.pad(allocator, &.{ .{padding[0], padding[0]}, .{padding[1], padding[1]}, .{0,0}, .{0,0} }) else input.*;
        defer if (padding[0] > 0 or padding[1] > 0) padded.deinit();
        for (0..batch) |b| for (0..oh) |oy| for (0..ow) |ox| for (0..oc) |out_c| {
            var sum: f32 = 0.0;
            for (0..kh) |ky| for (0..kw) |kx| for (0..ic) |in_c| {
                const y = oy * stride[0] + ky;
                const x = ox * stride[1] + kx;
                sum += padded.get(&.{b, y, x, in_c}) * kernel.get(&.{ky, kx, in_c, out_c});
            }
            output.set(&.{b, oy, ox, out_c}, sum);
        }
        return output;
    }

    pub fn maxPool2d(self: *const Tensor, allocator: mem.Allocator, kernel: [2]usize, stride: [2]usize, padding: [2]usize) !Tensor {
        if (self.shape.len != 4) return error.InvalidPool2d;
        const batch = self.shape[0];
        const ih = self.shape[1];
        const iw = self.shape[2];
        const channels = self.shape[3];
        const oh = (ih + 2 * padding[0] - kernel[0]) / stride[0] + 1;
        const ow = (iw + 2 * padding[1] - kernel[1]) / stride[1] + 1;
        var output = try init(allocator, &.{batch, oh, ow, channels});
        var padded = if (padding[0] > 0 or padding[1] > 0) try self.pad(allocator, &.{ .{padding[0], padding[0]}, .{padding[1], padding[1]}, .{0,0}, .{0,0} }) else self.*;
        defer if (padding[0] > 0 or padding[1] > 0) padded.deinit();
        for (0..batch) |b| for (0..oh) |oy| for (0..ow) |ox| for (0..channels) |c| {
            var max_v = -math.inf(f32);
            for (0..kernel[0]) |ky| for (0..kernel[1]) |kx| {
                const y = oy * stride[0] + ky;
                const x = ox * stride[1] + kx;
                max_v = math.max(max_v, padded.get(&.{b, y, x, c}));
            }
            output.set(&.{b, oy, ox, c}, max_v);
        }
        return output;
    }

    pub fn avgPool2d(self: *const Tensor, allocator: mem.Allocator, kernel: [2]usize, stride: [2]usize, padding: [2]usize) !Tensor {
        if (self.shape.len != 4) return error.InvalidPool2d;
        const batch = self.shape[0];
        const ih = self.shape[1];
        const iw = self.shape[2];
        const channels = self.shape[3];
        const oh = (ih + 2 * padding[0] - kernel[0]) / stride[0] + 1;
        const ow = (iw + 2 * padding[1] - kernel[1]) / stride[1] + 1;
        var output = try init(allocator, &.{batch, oh, ow, channels});
        var padded = if (padding[0] > 0 or padding[1] > 0) try self.pad(allocator, &.{ .{padding[0], padding[0]}, .{padding[1], padding[1]}, .{0,0}, .{0,0} }) else self.*;
        defer if (padding[0] > 0 or padding[1] > 0) padded.deinit();
        const area = @as(f32, @floatFromInt(kernel[0] * kernel[1]));
        for (0..batch) |b| for (0..oh) |oy| for (0..ow) |ox| for (0..channels) |c| {
            var sum: f32 = 0.0;
            for (0..kernel[0]) |ky| for (0..kernel[1]) |kx| {
                const y = oy * stride[0] + ky;
                const x = ox * stride[1] + kx;
                sum += padded.get(&.{b, y, x, c});
            }
            output.set(&.{b, oy, ox, c}, sum / area);
        }
        return output;
    }

    pub fn relu(self: *Tensor) void {
        for (self.data) |*val| val.* = math.max(0.0, val.*);
    }

    pub fn leakyRelu(self: *Tensor, alpha: f32) void {
        for (self.data) |*val| val.* = if (val.* > 0.0) val.* else alpha * val.*;
    }

    pub fn sigmoid(self: *Tensor) void {
        for (self.data) |*val| val.* = 1.0 / (1.0 + math.exp(-val.*));
    }

    pub fn tanh(self: *Tensor) void {
        for (self.data) |*val| val.* = math.tanh(val.*);
    }

    pub fn softmax(self: *Tensor, axis: usize) !void {
        var max_t = try self.max(self.allocator, axis);
        defer max_t.deinit();
        var b_shape = try self.allocator.alloc(usize, self.shape.len);
        defer self.allocator.free(b_shape);
        @memcpy(b_shape, self.shape);
        b_shape[axis] = 1;
        var b_max = try max_t.broadcast(self.allocator, b_shape);
        defer b_max.deinit();
        try self.sub(&b_max);
        self.exp();
        var sum_t = try self.sum(self.allocator, axis);
        defer sum_t.deinit();
        var b_sum = try sum_t.broadcast(self.allocator, b_shape);
        defer b_sum.deinit();
        try self.div(&b_sum);
    }

    pub fn logSoftmax(self: *Tensor, axis: usize) !void {
        try self.softmax(axis);
        self.log();
    }

    pub fn einsum(self: *const Tensor, other: *const Tensor, allocator: mem.Allocator, equation: []const u8) !Tensor {
        _ = self;
        _ = other;
        _ = allocator;
        _ = equation;
        return error.NotImplemented; // Placeholder for complex einsum implementation
    }

    pub fn fusedAddMul(self: *Tensor, add: *const Tensor, mul: *const Tensor) !void {
        try self.add(add);
        try self.mul(mul);
    }
};

