const std = @import("std");
const mem = std.mem;
const math = std.math;

pub const TensorRank = enum(u8) { scalar = 0, vector = 1, matrix = 2, tensor3 = 3, tensor4 = 4 };

pub fn Tensor(comptime T: type, comptime rank: TensorRank) type {
    return packed struct {
        data: [@intFromEnum(rank)]T,
        strides: [@intFromEnum(rank)]usize,

        pub fn init(allocator: mem.Allocator, shape: [@intFromEnum(rank)]usize) !@This() {
            var self: @This() = undefined;
            var total_size: usize = 1;
            for (shape) |s| total_size *= s;
            self.data = try allocator.alloc(T, total_size);
            var stride: usize = 1;
            var i = shape.len;
            while (i > 0) : (i -= 1) {
                self.strides[i - 1] = stride;
                stride *= shape[i - 1];
            }
            return self;
        }

        pub fn deinit(self: *@This(), allocator: mem.Allocator) void {
            allocator.free(self.data);
        }
    };
}

pub const FixedPoint = packed struct {
    integer: i32,
    fraction: u32,

    pub fn fromFloat(f: f64) @This() {
        const i = @trunc(f);
        const frac = @mod(f, 1.0) * @as(f64, @floatFromInt(math.maxInt(u32)));
        return .{ .integer = @intFromFloat(i), .fraction = @intFromFloat(frac) };
    }

    pub fn toFloat(self: @This()) f64 {
        return @floatFromInt(self.integer) + @as(f64, @floatFromInt(self.fraction)) / @as(f64, @floatFromInt(math.maxInt(u32)));
    }
};

pub const RankedSegment = packed struct {
    start_offset: u64,
    end_offset: u64,
    score: FixedPoint,
    hash_key: [32]u8,
};

pub const ContextWindow = packed struct {
    segments: [1024]RankedSegment,
    count: u16,
    total_tokens: u64,
};

pub const MorphemeNode = packed struct {
    children: [256]*MorphemeNode,
    is_end: bool,
    token_id: u32,
    freq: u64,

    pub fn init(allocator: mem.Allocator) !*@This() {
        const node = try allocator.create(@This());
        mem.set(*MorphemeNode, &node.children, null);
        node.is_end = false;
        node.token_id = 0;
        node.freq = 0;
        return node;
    }
};
