const std = @import("std");
const mem = std.mem;
const os = std.os;
const math = std.math;

const Arena = struct {
    base: [*]u8,
    size: usize,
    used: usize,
    thread_id: u64,

    pub fn init(size: usize) !@This() {
        const mapping = try os.mmap(null, size, os.PROT.READ | os.PROT.WRITE, os.MAP.PRIVATE | os.MAP.ANONYMOUS, -1, 0);
        return .{ .base = mapping.ptr, .size = size, .used = 0, .thread_id = std.Thread.getCurrentId() };
    }

    pub fn deinit(self: *@This()) void {
        os.munmap(self.base[0..self.size]);
    }

    pub fn alloc(self: *@This(), comptime T: type, n: usize) ![]T {
        const align_size = mem.alignForward(usize, n * @sizeOf(T), @alignOf(T));
        if (self.used + align_size > self.size) return error.OutOfMemory;
        const ptr = @ptrCast([*]T, @alignCast(@alignOf(T), self.base + self.used));
        self.used += align_size;
        return ptr[0..n];
    }

    pub fn reset(self: *@This()) void {
        self.used = 0;
    }
};

const GlobalArena = struct {
    arenas: std.ArrayList(Arena),
    mutex: std.Thread.Mutex,
    shared_pages: std.AutoHashMap(u64, []u8),

    pub fn init(allocator: mem.Allocator) @This() {
        return .{ .arenas = std.ArrayList(Arena).init(allocator), .mutex = .{}, .shared_pages = std.AutoHashMap(u64, []u8).init(allocator) };
    }

    pub fn deinit(self: *@This()) void {
        for (self.arenas.items) |*arena| arena.deinit();
        self.arenas.deinit();
        var iter = self.shared_pages.iterator();
        while (iter.next()) |entry| {
            os.munmap(entry.value_ptr.*);
        }
        self.shared_pages.deinit();
    }

    pub fn createArena(self: *@This(), size: usize) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        const arena = try Arena.init(size);
        try self.arenas.append(arena);
    }

    pub fn getThreadArena(self: *@This()) !*Arena {
        const tid = std.Thread.getCurrentId();
        self.mutex.lock();
        defer self.mutex.unlock();
        for (self.arenas.items) |*arena| {
            if (arena.thread_id == tid) return arena;
        }
        try self.createArena(1 << 30); // 1GB default
        return &self.arenas.items[self.arenas.items.len - 1];
    }

    pub fn zeroCopyPass(self: *@This(), data: []u8, target_thread: u64) !void {
        const page_size = std.mem.page_size;
        const aligned_len = mem.alignForward(usize, data.len, page_size);
        const shared = try os.mmap(null, aligned_len, os.PROT.READ | os.PROT.WRITE, os.MAP.SHARED | os.MAP.ANONYMOUS, -1, 0);
        @memcpy(shared, data);
        self.mutex.lock();
        defer self.mutex.unlock();
        try self.shared_pages.put(target_thread, shared);
    }

    pub fn receiveZeroCopy(self: *@This()) ?[]u8 {
        const tid = std.Thread.getCurrentId();
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.shared_pages.get(tid)) |shared| {
            _ = self.shared_pages.remove(tid);
            return shared;
        }
        return null;
    }
};

var global_arena: GlobalArena = undefined;

pub fn initGlobalArena(allocator: mem.Allocator) void {
    global_arena = GlobalArena.init(allocator);
}

pub fn deinitGlobalArena() void {
    global_arena.deinit();
}

pub fn threadAlloc(comptime T: type, n: usize) ![]T {
    var arena = try global_arena.getThreadArena();
    return try arena.alloc(T, n);
}

pub fn threadReset() void {
    if (global_arena.getThreadArena()) |arena| {
        arena.reset();
    }
}

pub fn shareData(data: []u8, target: u64) !void {
    try global_arena.zeroCopyPass(data, target);
}

pub fn receiveData() ?[]u8 {
    return global_arena.receiveZeroCopy();
}

pub fn allocLargeShared(size: usize) ![]u8 {
    const mapping = try os.mmap(null, size, os.PROT.READ | os.PROT.WRITE, os.MAP.SHARED | os.MAP.ANONYMOUS, -1, 0);
    return mapping;
}

pub fn protectRegion(ptr: [*]u8, len: usize, prot: u32) !void {
    try os.mprotect(ptr[0..len], prot);
}

pub fn adviseRegion(ptr: [*]u8, len: usize, advice: i32) !void {
    _ = try os.madvise(ptr, len, advice);
}

pub fn lockPages(ptr: [*]u8, len: usize) !void {
    try os.mlock(ptr[0..len]);
}

pub fn unlockPages(ptr: [*]u8, len: usize) void {
    os.munlock(ptr[0..len]) catch {};
}

pub fn prefetchData(ptr: [*]const u8, len: usize) void {
    const pages = @divFloor(len, std.mem.page_size);
    for (0..pages) |i| {
        const page_ptr = ptr + i * std.mem.page_size;
        @prefetch(page_ptr, .{ .locality = 3, .rw = .read, .cache = .data });
    }
}

pub fn alignPtr(ptr: anytype, alignment: usize) @TypeOf(ptr) {
    const addr = @intFromPtr(ptr);
    const aligned_addr = mem.alignForward(usize, addr, alignment);
    return @ptrFromInt(aligned_addr);
}

pub fn cacheFlush(ptr: [*]u8, len: usize) void {
    @fence(.SeqCst);
    const cache_line = 64;
    var i: usize = 0;
    while (i < len) : (i += cache_line) {
        std.atomic.compilerFence(.SeqCst);
        asm volatile ("clflush (%[ptr])"
            :
            : [ptr] "r" (ptr + i)
            : "memory"
        );
    }
}

pub fn secureZero(mem_ptr: [*]u8, len: usize) void {
    @memset(mem_ptr[0..len], 0);
    cacheFlush(mem_ptr, len);
    @fence(.SeqCst);
}

pub fn randomFill(buf: []u8) void {
    var prng = std.rand.DefaultPrng.init(@intCast(std.time.milliTimestamp()));
    prng.random().bytes(buf);
}

pub fn memCompareSecure(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    var diff: u8 = 0;
    for (a, b) |x, y| {
        diff |= x ^ y;
    }
    return diff == 0;
}

pub fn batchAlloc(comptime T: type, batches: usize, batch_size: usize) ![][]T {
    var outer = try threadAlloc([]T, batches);
    for (0..batches) |i| {
        outer[i] = try threadAlloc(T, batch_size);
    }
    return outer;
}

pub fn defragmentArenas() void {
    global_arena.mutex.lock();
    defer global_arena.mutex.unlock();
    for (global_arena.arenas.items) |*arena| {
        const used_pages = math.divCeil(usize, arena.used, std.mem.page_size) catch 0;
        const unused_start = arena.base + used_pages * std.mem.page_size;
        const unused_len = arena.size - used_pages * std.mem.page_size;
        if (unused_len > 0) {
            os.madvise(unused_start, unused_len, os.MADV.DONTNEED) catch {};
        }
    }
}

pub fn profileMemoryUsage() usize {
    var total: usize = 0;
    global_arena.mutex.lock();
    defer global_arena.mutex.unlock();
    for (global_arena.arenas.items) |arena| {
        total += arena.used;
    }
    var iter = global_arena.shared_pages.iterator();
    while (iter.next()) |entry| {
        total += entry.value_ptr.len;
    }
    return total;
}

pub fn dumpMemoryStats(writer: anytype) !void {
    const usage = profileMemoryUsage();
