        var out = try Tensor.init(allocator, &[_]usize{ self.shape[0], num_classes });
        out.fill(0.0);
        var i: usize = 0;
        while (i < self.shape[0]) : (i += 1) {
            const cls = @intFromFloat(usize, self.data[i]);
            if (cls < num_classes) out.data[i * num_classes + cls] = 1.0;
        }
        return out;
    }

    pub fn cumsum(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        if (axis >= self.shape.len) return Error.InvalidAxis;
        var out = try self.copy(allocator);
        var idx = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(idx);
        @memset(idx, 0);
        var done = false;
        while (!done) {
            if (idx[axis] > 0) {
                const curr = out.data[out.getIndex(idx)];
                var prev_idx = try allocator.dupe(usize, idx);
                prev_idx[axis] -= 1;
                out.data[out.getIndex(idx)] = curr + out.data[out.getIndex(prev_idx)];
                allocator.free(prev_idx);
            }
            var p = self.shape.len;
            done = true;
            while (p > 0) {
                p -= 1;
                if (p != axis) {
                    idx[p] += 1;
                    if (idx[p] < self.shape[p]) {
                        done = false;
                        break;
                    }
                    idx[p] = 0;
                } else {
                    if (p == 0) {}
                }
            }
        }
        return out;
    }

    pub fn cumprod(self: *const Tensor, allocator: mem.Allocator, axis: usize) !Tensor {
        if (axis >= self.shape.len) return Error.InvalidAxis;
        var out = try self.copy(allocator);
        var idx = try allocator.alloc(usize, self.shape.len);
        defer allocator.free(idx);
        @memset(idx, 0);
        var done = false;
        while (!done) {
            if (idx[axis] > 0) {
                const curr = out.data[out.getIndex(idx)];
                var prev_idx = try allocator.dupe(usize, idx);
                prev_idx[axis] -= 1;
                out.data[out.getIndex(idx)] = curr * out.data[out.getIndex(prev_idx)];
                allocator.free(prev_idx);
            }
            var p = self.shape.len;
            done = true;
            while (p > 0) {
                p -= 1;
                if (p != axis) {
                    idx[p] += 1;
                    if (idx[p] < self.shape[p]) {
