    pub fn sort(self: *const Tensor, allocator: mem.Allocator, axis: usize, descending: bool) !Tensor {
        if (axis >= self.shape.len) return Error.InvalidAxis;
        var out = try self.copy(allocator);
        const dim = self.shape[axis];
        var idx = try allocator.alloc(usize, self.shape.len);
        var tmp = try allocator.alloc(f32, dim);
        defer allocator.free(tmp);
        defer allocator.free(idx);
        @memset(idx, 0);
        var done = false;
        while (!done) {
            var i: usize = 0;
            while (i < dim) : (i += 1) {
                idx[axis] = i;
                tmp[i] = out.data[out.getIndex(idx)];
            }
            if (descending) {
                std.sort.sort(f32, tmp, {}, comptime std.sort.desc(f32));
            } else {
                std.sort.sort(f32, tmp, {}, comptime std.sort.asc(f32));
            }
            i = 0;
            while (i < dim) : (i += 1) {
                idx[axis] = i;
                out.data[out.getIndex(idx)] = tmp[i];
            }
            var p = self.shape.len;
            done = true;
            while (p > 0) {
                p -= 1;
                if (p != axis) {
                    idx[p] += 1;
                    if (idx[p] < self.shape[p]) {
                        done = false;
                        break;
                    }
                    idx[p] = 0;
                }
            }
        }
        return out;
    }

    pub fn unique(self: *const Tensor, allocator: mem.Allocator) !Tensor {
        var set = std.AutoHashMap(f32, void).init(allocator);
        defer set.deinit();
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) try set.put(self.data[i], {});
        var result = try Tensor.init(allocator, &[_]usize{ set.count() });
        var it = set.keyIterator();
        var k: usize = 0;
        while (it.next()) |key| : (k += 1) result.data[k] = key.*;
        return result;
    }

    pub fn isClose(self: *const Tensor, other: *const Tensor, rtol: f32, atol: f32) bool {
        if (!shapesEqual(self.shape, other.shape)) return false;
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            if (math.fabs(self.data[i] - other.data[i]) > atol + rtol * math.fabs(other.data[i])) return false;
        }
        return true;
    }

    pub fn randomUniform(self: *Tensor, minv: f32, maxv: f32, seed: u64) void {
        var prng = std.rand.DefaultPrng.init(seed);
        const rng = prng.random();
        var i: usize = 0;
        const span = maxv - minv;
        while (i < self.data.len) : (i += 1) self.data[i] = rng.float(f32) * span + minv;
    }

    pub fn randomNormal(self: *Tensor, mean: f32, stddev: f32, seed: u64) void {
        var prng = std.rand.DefaultPrng.init(seed);
        const rng = prng.random();
        var i: usize = 0;
        while (i < self.data.len) : (i += 2) {
            const u1 = math.max(rng.float(f32), 1e-7);
            const u2 = rng.float(f32);
            const r = math.sqrt(-2.0 * math.log(u1));
            const z0 = r * math.cos(2.0 * math.pi * u2);
            self.data[i] = mean + stddev * z0;
            if (i + 1 < self.data.len) {
                const z1 = r * math.sin(2.0 * math.pi * u2);
                self.data[i + 1] = mean + stddev * z1;
            }
        }
    }

    pub fn arange(allocator: mem.Allocator, start: f32, end: f32, step: f32) !Tensor {
        const n_f = (end - start) / step;
        const n = if (n_f <= 0) 0 else @intFromFloat(usize, math.ceil(n_f));
        var out = try Tensor.init(allocator, &[_]usize{ n });
        var v = start;
        var i: usize = 0;
        while (i < n) : (i += 1) {
            out.data[i] = v;
            v += step;
        }
        return out;
    }

    pub fn linspace(allocator: mem.Allocator, start: f32, end: f32, num: usize) !Tensor {
        if (num == 0) return Tensor.init(allocator, &[_]usize{0});
        var out = try Tensor.init(allocator, &[_]usize{ num });
        if (num == 1) {
            out.data[0] = start;
            return out;
        }
        const step = (end - start) / @as(f32, @floatFromInt(num - 1));
        var v = start;
        var i: usize = 0;
        while (i + 1 < num) : (i += 1) {
            out.data[i] = v;
            v += step;
        }
        out.data[num - 1] = end;
        return out;
    }

    pub fn eye(allocator: mem.Allocator, n: usize) !Tensor {
        if (n == 0) return Tensor.init(allocator, &[_]usize{0, 0});
        var out = try Tensor.init(allocator, &[_]usize{ n, n });
        out.fill(0.0);
        var i: usize = 0;
        while (i < n) : (i += 1) out.data[i * n + i] = 1.0;
        return out;
    }

    pub fn zeros(allocator: mem.Allocator, shape: []const usize) !Tensor {
        var out = try Tensor.init(allocator, shape);
        out.fill(0.0);
        return out;
    }

    pub fn ones(allocator: mem.Allocator, shape: []const usize) !Tensor {
        var out = try Tensor.init(allocator, shape);
        out.fill(1.0);
        return out;
    }

    pub fn full(allocator: mem.Allocator, shape: []const usize, value: f32) !Tensor {
        var out = try Tensor.init(allocator, shape);
        out.fill(value);
        return out;
    }

    pub fn matmul(a: *const Tensor, b: *const Tensor, allocator: mem.Allocator) !Tensor {
        if (a.shape.len != 2 or b.shape.len != 2) return Error.InvalidMatmul;
        const m = a.shape[0];
        const k = a.shape[1];
        const kb = b.shape[0];
        const n = b.shape[1];
        if (k != kb) return Error.InvalidMatmul;
        var c = try Tensor.init(allocator, &[_]usize{ m, n });
        c.fill(0.0);
        var bT = try Tensor.init(allocator, &[_]usize{ n, k });
        {
            var i: usize = 0;
            while (i < k) : (i += 1) {
                var j: usize = 0;
                while (j < n) : (j += 1) {
                    bT.data[j * k + i] = b.data[i * n + j];
                }
            }
        }
        {
            var i: usize = 0;
            while (i < m) : (i += 1) {
                var j: usize = 0;
                while (j < n) : (j += 1) {
                    var sum: f32 = 0.0;
                    var p: usize = 0;
                    while (p < k) : (p += 1) {
                        sum += a.data[i * k + p] * bT.data[j * k + p];
                    }
                    c.data[i * n + j] = sum;
                }
            }
        }
        bT.deinit();
        return c;
    }

    pub fn conv2d(input: *const Tensor, kernel: *const Tensor, allocator: mem.Allocator, stride: [2]usize, padding: [2]usize) !Tensor {
        if (input.shape.len != 4 or kernel.shape.len != 4) return Error.InvalidConv2d;
        const batch = input.shape[0];
        const ih = input.shape[1];
        const iw = input.shape[2];
        const ic = input.shape[3];
        const kh = kernel.shape[0];
        const kw = kernel.shape[1];
        const kc = kernel.shape[2];
        const oc = kernel.shape[3];
        if (kc != ic) return Error.InvalidConv2d;
        const oh = (ih + 2 * padding[0] - kh) / stride[0] + 1;
        const ow = (iw + 2 * padding[1] - kw) / stride[1] + 1;
        var out = try Tensor.init(allocator, &[_]usize{ batch, oh, ow, oc });
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oy: usize = 0;
            while (oy < oh) : (oy += 1) {
                var ox: usize = 0;
                while (ox < ow) : (ox += 1) {
                    var ocv: usize = 0;
                    while (ocv < oc) : (ocv += 1) {
                        var sum: f32 = 0.0;
                        var ky: usize = 0;
                        while (ky < kh) : (ky += 1) {
                            var kx: usize = 0;
                            while (kx < kw) : (kx += 1) {
                                var icv: usize = 0;
                                while (icv < ic) : (icv += 1) {
                                    const y = @as(isize, @intCast(oy * stride[0] + ky));
                                    const x = @as(isize, @intCast(ox * stride[1] + kx));
                                    const yy = y - @as(isize, @intCast(padding[0]));
                                    const xx = x - @as(isize, @intCast(padding[1]));
                                    if (yy >= 0 and xx >= 0 and @as(usize, @intCast(yy)) < ih and @as(usize, @intCast(xx)) < iw) {
                                        const iv = input.data[((b * ih + @as(usize, @intCast(yy))) * iw + @as(usize, @intCast(xx))) * ic + icv];
                                        const kv = kernel.data[((ky * kw + kx) * ic + icv) * oc + ocv];
                                        sum += iv * kv;
                                    }
                                }
                            }
                        }
                        out.data[((b * oh + oy) * ow + ox) * oc + ocv] = sum;
                    }
                }
            }
        }
        return out;
    }

    pub fn maxPool2d(self: *const Tensor, allocator: mem.Allocator, kernel: [2]usize, stride: [2]usize, padding: [2]usize) !Tensor {
        if (self.shape.len != 4) return Error.InvalidPool2d;
        const batch = self.shape[0];
        const ih = self.shape[1];
        const iw = self.shape[2];
        const ch = self.shape[3];
        const oh = (ih + 2 * padding[0] - kernel[0]) / stride[0] + 1;
        const ow = (iw + 2 * padding[1] - kernel[1]) / stride[1] + 1;
        var out = try Tensor.init(allocator, &[_]usize{ batch, oh, ow, ch });
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oy: usize = 0;
            while (oy < oh) : (oy += 1) {
                var ox: usize = 0;
                while (ox < ow) : (ox += 1) {
                    var c: usize = 0;
                    while (c < ch) : (c += 1) {
                        var mval: f32 = -math.inf(f32);
                        var ky: usize = 0;
                        while (ky < kernel[0]) : (ky += 1) {
                            var kx: usize = 0;
                            while (kx < kernel[1]) : (kx += 1) {
                                const y = @as(isize, @intCast(oy * stride[0] + ky)) - @as(isize, @intCast(padding[0]));
                                const x = @as(isize, @intCast(ox * stride[1] + kx)) - @as(isize, @intCast(padding[1]));
                                if (y >= 0 and x >= 0 and @as(usize, @intCast(y)) < ih and @as(usize, @intCast(x)) < iw) {
                                    const v = self.data[((b * ih + @as(usize, @intCast(y))) * iw + @as(usize, @intCast(x))) * ch + c];
                                    if (v > mval) mval = v;
                                }
                            }
                        }
                        out.data[((b * oh + oy) * ow + ox) * ch + c] = mval;
                    }
                }
            }
        }
        return out;
    }

    pub fn avgPool2d(self: *const Tensor, allocator: mem.Allocator, kernel: [2]usize, stride: [2]usize, padding: [2]usize) !Tensor {
        if (self.shape.len != 4) return Error.InvalidPool2d;
        const batch = self.shape[0];
        const ih = self.shape[1];
        const iw = self.shape[2];
        const ch = self.shape[3];
        const oh = (ih + 2 * padding[0] - kernel[0]) / stride[0] + 1;
        const ow = (iw + 2 * padding[1] - kernel[1]) / stride[1] + 1;
        var out = try Tensor.init(allocator, &[_]usize{ batch, oh, ow, ch });
        const area = @as(f32, @floatFromInt(kernel[0] * kernel[1]));
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oy: usize = 0;
            while (oy < oh) : (oy += 1) {
                var ox: usize = 0;
                while (ox < ow) : (ox += 1) {
                    var c: usize = 0;
                    while (c < ch) : (c += 1) {
                        var sum: f32 = 0.0;
                        var ky: usize = 0;
                        while (ky < kernel[0]) : (ky += 1) {
                            var kx: usize = 0;
                            while (kx < kernel[1]) : (kx += 1) {
                                const y = @as(isize, @intCast(oy * stride[0] + ky)) - @as(isize, @intCast(padding[0]));
                                const x = @as(isize, @intCast(ox * stride[1] + kx)) - @as(isize, @intCast(padding[1]));
                                if (y >= 0 and x >= 0 and @as(usize, @intCast(y)) < ih and @as(usize, @intCast(x)) < iw) {
                                    const v = self.data[((b * ih + @as(usize, @intCast(y))) * iw + @as(usize, @intCast(x))) * ch + c];
                                    sum += v;
                                }
                            }
                        }
                        out.data[((b * oh + oy) * ow + ox) * ch + c] = sum / area;
                    }
                }
            }
        }
        return out;
    }

    pub fn relu(self: *Tensor) void {
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) self.data[i] = if (self.data[i] > 0.0) self.data[i] else 0.0;
    }

    pub fn leakyRelu(self: *Tensor, alpha: f32) void {
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) self.data[i] = if (self.data[i] > 0.0) self.data[i] else alpha * self.data[i];
    }

    pub fn sigmoid(self: *Tensor) void {
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) self.data[i] = 1.0 / (1.0 + math.exp(-self.data[i]));
    }

    pub fn tanh(self: *Tensor) void {
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) self.data[i] = math.tanh(self.data[i]);
    }

    pub fn softmax(self: *Tensor, allocator: mem.Allocator, axis: usize) !void {
        var max_t = try self.max(allocator, axis);
        var b_shape = try allocator.dupe(usize, self.shape);
        b_shape[axis] = 1;
        var b_max = try max_t.broadcast(allocator, b_shape);
        try self.sub(&b_max);
        self.exp();
        var sum_t = try self.sum(allocator, axis);
        var b_sum = try sum_t.broadcast(allocator, b_shape);
        try self.div(&b_sum);
        b_sum.deinit();
        sum_t.deinit();
        b_max.deinit();
        allocator.free(b_shape);
        max_t.deinit();
    }

    pub fn logSoftmax(self: *Tensor, allocator: mem.Allocator, axis: usize) !void {
        try self.softmax(allocator, axis);
        self.log();
    }

    pub fn fusedAddMul(self: *Tensor, add: *const Tensor, mul: *const Tensor) !void {
        try self.add(add);
        try self.mul(mul);
    }
};

